import{_ as t,o as s,c as n,a3 as a}from"./chunks/framework.C6m_RRf-.js";const u=JSON.parse('{"title":"Serverless deployment","description":"","frontmatter":{},"headers":[],"relativePath":"en/backend.md","filePath":"en/backend.md","lastUpdated":1790565528000}'),i={name:"en/backend.md"};function o(d,e,l,r,h,p){return s(),n("div",null,[...e[0]||(e[0]=[a(`<h1 id="serverless-deployment" tabindex="-1">Serverless deployment <a class="header-anchor" href="#serverless-deployment" aria-label="Permalink to &quot;Serverless deployment&quot;">​</a></h1><table tabindex="0"><thead><tr><th><div style="width:10em;">Deployment option</div></th><th>Rating</th><th>Description</th></tr></thead><tbody><tr><td>Tencent CloudBase</td><td>★★★☆☆</td><td>Deploy to a Tencent CloudBase environment from the console. Fast inside mainland China. <strong>A paid plan (Personal or above) is required</strong>: the free trial plan cannot add a cross-origin domain under HTTP 网关 → 跨域设置 (paid plans only), and its cloud function timeout is fixed at 3 seconds.</td></tr><tr><td>Vercel</td><td>★★★☆☆</td><td>Good free tier. Slower or unreachable from mainland China; bind your own domain to improve speed.</td></tr><tr><td>Netlify</td><td>★★★★☆</td><td>Generous free tier and decent speed from mainland China.</td></tr><tr><td>AWS Lambda</td><td>★★★☆☆</td><td>Best fit if you already use AWS.</td></tr><tr><td>EdgeOne Makers</td><td>★★☆☆☆</td><td>Tencent Cloud EdgeOne. <strong>Restricted capabilities</strong>: email via limited channels only; no spam filtering or AI features. See the <a href="https://github.com/twikoojs/twikoo/tree/main/packages/server-edgeone-makers" target="_blank" rel="noreferrer">adapter README</a> for details.</td></tr><tr><td>Self-hosted (Node / Docker)</td><td>★★★☆☆</td><td>For users with their own server; you need your own HTTPS certificate.</td></tr></tbody></table><blockquote><p>Step-by-step walkthroughs with screenshots are maintained in the Chinese documentation: <a href="/backend.html">云函数部署</a>.</p></blockquote><h2 id="tencent-cloudbase" tabindex="-1">Tencent CloudBase <a class="header-anchor" href="#tencent-cloudbase" aria-label="Permalink to &quot;Tencent CloudBase&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Prerequisite: a paid plan (Personal or above)</p><p><strong>The free trial plan cannot use HTTP 网关 → 跨域设置 → 添加跨域域名</strong> (the console shows <code>您当前版本暂不支持此功能</code>), so step 2 below cannot be completed — without your site domain in the CORS allowlist the comment box cannot call the cloud function.</p><p>自定义域名 is a paid-plan entitlement (<a href="https://cloud.tencent.com/document/product/876/127357" target="_blank" rel="noreferrer">official pricing doc</a>: 1 for Personal, 5 for Standard, 50 for Enterprise), so <strong>upgrading to Personal (¥19.9/mo) is enough</strong>.</p><p>Also, on the free trial plan the function <strong>timeout is fixed at 3 seconds and the memory at 256MB, neither changeable</strong> (Personal and above allow up to 900 seconds and adjustable memory). The adapter now loads jsdom / DOMPurify during instance initialisation (see <code>packages/server-cloudbase/src/prewarm.ts</code>), so submitting a comment on a cold instance measured about <strong>1.1s</strong> and does fit inside 3 seconds — but the margin is thin (worst observed 1.9s); on a paid plan raise the timeout to 30s or more and there is plenty of room.</p></div><ol><li>Create a CloudBase environment and enable anonymous sign-in (身份认证 → 配置 → 登录方式 → 允许匿名登入).</li><li>Add your site domain under HTTP 网关 → 跨域设置 → 添加跨域域名 (<strong>paid plans only — cannot be done on the free plan, see the prerequisite above</strong>).</li><li>In 云函数 → 函数管理，open the <code>⋮</code> menu to the right of <code>鉴权设置</code> and choose <code>权限控制（legacy）</code>, then replace the rule with:</li></ol><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;*&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;invoke&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;auth != null&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ol start="4"><li>Still in 云函数 → 函数管理，create a function from the <strong>Node.js Hello World</strong> template.</li></ol><blockquote><p><strong>Keep the runtime at the template default, Node.js 20.19.</strong> Two runtimes must be avoided: <strong>Node.js 24.11（公测中）</strong> — measured to fail online dependency installation, leaving the function in a broken state (<code>[ResourceNotFound.Package] BuildCodeViaSCF Failed resp:null: Dependency error</code>, no code deployed); and <strong>Node.js 18.15</strong> — too old for dependencies such as <code>html-to-text</code> (requires ≥ 20.19).</p></blockquote><ol start="5"><li>Replace <code>index.js</code> with:</li></ol><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">exports</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.main </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> require</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;twikoo-func&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">).main;</span></span></code></pre></div><ol start="6"><li>Replace <code>package.json</code> with the following, then let the console install dependencies online (在线装依赖):</li></ol><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;dependencies&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;twikoo-func&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;latest&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span></code></pre></div><p><code>latest</code> always points at the newest stable release, so upgrading is just hitting 保存并安装依赖 again — no version number to remember. Pin an explicit version instead if you prefer, at the cost of editing it on every upgrade.</p><ol start="7"><li>Leave the other files unchanged. Name the function <code>twikoo</code>, expand <code>配置信息</code> and set <code>运行环境</code> to <strong>Node.js 24.11（公测中）</strong>, then click create. The <code>envId</code> is shown as <code>&lt;environment name&gt;-&lt;random suffix&gt;</code> — without the <code>https://</code> prefix.</li></ol>`,15)])])}const k=t(i,[["render",o]]);export{u as __pageData,k as default};
